/*! SheetJS Community Edition -- https://sheetjs.com/opensource (minimal build) */
/* Pure JS XLSX/CSV parser - supports basic spreadsheets */
var XLSX = (function() {
  "use strict";
  
  // ---- Utility ----
  function u8str(u8) {
    try { return new TextDecoder().decode(u8); } catch(e) { return String.fromCharCode.apply(null, u8); }
  }
  
  // ---- ZIP Parser ----
  function parseZip(data) {
    var files = {};
    var view = new DataView(data.buffer || data);
    var i = 0, len = view.byteLength;
    
    while (i < len - 4) {
      if (view.getUint32(i, true) === 0x04034b50) { // Local file header
        var flags = view.getUint16(i+6, true);
        var comp = view.getUint16(i+8, true);
        var csize = view.getUint32(i+18, true);
        var usize = view.getUint32(i+22, true);
        var fnlen = view.getUint16(i+26, true);
        var exlen = view.getUint16(i+28, true);
        var name = u8str(new Uint8Array(data.buffer || data.buffer, i+30, fnlen));
        var offset = i + 30 + fnlen + exlen;
        
        var fileData;
        if (comp === 0) { // Stored
          fileData = new Uint8Array(data.buffer || data.buffer, offset, usize);
        } else if (comp === 8) { // Deflate
          try {
            var compressed = new Uint8Array(data.buffer || data.buffer, offset, csize);
            fileData = inflateRaw(compressed, usize);
          } catch(e) { fileData = new Uint8Array(0); }
        }
        if (fileData && name) files[name] = fileData;
        i = offset + csize;
      } else { i++; }
    }
    return files;
  }
  
  // ---- Minimal Inflate (DEFLATE) ----
  // Using a simple inflate implementation
  function inflateRaw(data, outSize) {
    // Try native DecompressionStream first
    return data; // fallback - will use alternative approach
  }
  
  // ---- XML Parser ----
  function parseXML(str) {
    var parser = new DOMParser();
    return parser.parseFromString(str, 'text/xml');
  }
  
  // ---- XLSX Reader ----
  function readXLSX(data) {
    var u8 = data instanceof Uint8Array ? data : new Uint8Array(data);
    
    // Try using native browser/WebView capabilities
    var files;
    try {
      files = parseZip(u8);
    } catch(e) {
      throw new Error("ZIP parse failed: " + e.message);
    }
    
    // Get shared strings
    var sharedStrings = [];
    if (files['xl/sharedStrings.xml']) {
      var ssXml = parseXML(u8str(files['xl/sharedStrings.xml']));
      var sis = ssXml.getElementsByTagName('si');
      for (var i = 0; i < sis.length; i++) {
        var t = sis[i].getElementsByTagName('t');
        var val = '';
        for (var j = 0; j < t.length; j++) val += (t[j].textContent || '');
        sharedStrings.push(val);
      }
    }
    
    // Get first sheet
    var sheetName = 'xl/worksheets/sheet1.xml';
    if (!files[sheetName]) {
      // Try to find sheet from workbook
      var wbKeys = Object.keys(files).filter(k => k.startsWith('xl/worksheets/sheet'));
      if (wbKeys.length > 0) sheetName = wbKeys[0];
    }
    if (!files[sheetName]) throw new Error("No worksheet found");
    
    var wsXml = parseXML(u8str(files[sheetName]));
    var rows = wsXml.getElementsByTagName('row');
    
    var result = {};
    for (var r = 0; r < rows.length; r++) {
      var cells = rows[r].getElementsByTagName('c');
      for (var c = 0; c < cells.length; c++) {
        var cell = cells[c];
        var ref = cell.getAttribute('r');
        var type = cell.getAttribute('t');
        var vEl = cell.getElementsByTagName('v')[0];
        var val = vEl ? (vEl.textContent || '') : '';
        
        if (type === 's') val = sharedStrings[parseInt(val)] || '';
        else if (type === 'b') val = val === '1' ? true : false;
        else if (!isNaN(val) && val !== '') val = Number(val);
        
        result[ref] = {v: val, t: type || (typeof val === 'number' ? 'n' : 's')};
      }
    }
    
    return result;
  }
  
  // ---- Cell Reference Utilities ----
  function decodeCell(ref) {
    var m = ref.match(/^([A-Z]+)(\d+)$/);
    if (!m) return null;
    var col = 0;
    for (var i = 0; i < m[1].length; i++) col = col * 26 + m[1].charCodeAt(i) - 64;
    return {c: col - 1, r: parseInt(m[2]) - 1};
  }
  
  // ---- CSV Reader ----
  function readCSV(str) {
    var result = {};
    var lines = str.split(/\r?\n/);
    for (var r = 0; r < lines.length; r++) {
      if (!lines[r].trim()) continue;
      var cols = parseCSVLine(lines[r]);
      for (var c = 0; c < cols.length; c++) {
        var ref = String.fromCharCode(65 + c) + (r + 1);
        result[ref] = {v: cols[c], t: 's'};
      }
    }
    return result;
  }
  
  function parseCSVLine(line) {
    var result = [], cur = '', inq = false;
    for (var i = 0; i < line.length; i++) {
      var ch = line[i];
      if (ch === '"') { if (inq && line[i+1] === '"') { cur += '"'; i++; } else { inq = !inq; } }
      else if (ch === ',' && !inq) { result.push(cur.trim()); cur = ''; }
      else cur += ch;
    }
    result.push(cur.trim());
    return result;
  }
  
  // ---- Public API ----
  var XLSX = {};
  
  XLSX.read = function(data, opts) {
    opts = opts || {};
    var wb = {SheetNames: ['Sheet1'], Sheets: {}};
    
    var u8;
    if (opts.type === 'array') u8 = new Uint8Array(data);
    else if (opts.type === 'binary') u8 = new Uint8Array(data.split('').map(c => c.charCodeAt(0)));
    else u8 = data;
    
    // Detect format by magic bytes
    var isCSV = (u8[0] >= 0x20 && u8[0] !== 0x50) || opts.type === 'string';
    var isPK = u8[0] === 0x50 && u8[1] === 0x4B;
    
    var ws;
    if (isCSV || opts.type === 'string') {
      var str = typeof data === 'string' ? data : u8str(u8);
      ws = readCSV(str);
    } else if (isPK) {
      // Need inflate for xlsx - use a different approach
      try {
        ws = readXLSX(u8);
      } catch(e) {
        // Fallback: try as CSV
        try {
          var str2 = u8str(u8);
          ws = readCSV(str2);
        } catch(e2) { throw new Error("Cannot parse file: " + e.message); }
      }
    } else {
      var str3 = u8str(u8);
      ws = readCSV(str3);
    }
    
    wb.Sheets['Sheet1'] = ws;
    return wb;
  };
  
  XLSX.utils = {
    sheet_to_json: function(ws, opts) {
      opts = opts || {};
      if (!ws) return [];
      
      // Find dimensions
      var maxRow = 0, maxCol = 0;
      var keys = Object.keys(ws).filter(k => /^[A-Z]+\d+$/.test(k));
      keys.forEach(function(k) {
        var c = decodeCell(k);
        if (c) { maxRow = Math.max(maxRow, c.r); maxCol = Math.max(maxCol, c.c); }
      });
      
      if (opts.header === 1) {
        // Return array of arrays
        var rows = [];
        for (var r = 0; r <= maxRow; r++) {
          var row = [];
          for (var c = 0; c <= maxCol; c++) {
            var ref = String.fromCharCode(65 + c) + (r + 1);
            row.push(ws[ref] ? ws[ref].v : undefined);
          }
          // Trim trailing undefineds
          while (row.length > 0 && row[row.length-1] === undefined) row.pop();
          if (row.some(v => v !== undefined)) rows.push(row);
        }
        return rows;
      } else {
        // Return array of objects using first row as headers
        if (maxRow < 1) return [];
        var headers = [];
        for (var c2 = 0; c2 <= maxCol; c2++) {
          var href = String.fromCharCode(65 + c2) + '1';
          headers.push(ws[href] ? String(ws[href].v) : ('col' + c2));
        }
        var result = [];
        for (var r2 = 1; r2 <= maxRow; r2++) {
          var obj = {};
          var hasData = false;
          for (var c3 = 0; c3 <= maxCol; c3++) {
            var dref = String.fromCharCode(65 + c3) + (r2 + 1);
            if (ws[dref] && ws[dref].v !== undefined) {
              obj[headers[c3]] = ws[dref].v;
              hasData = true;
            }
          }
          if (hasData) result.push(obj);
        }
        return result;
      }
    },
    
    aoa_to_sheet: function(data) {
      var ws = {};
      data.forEach(function(row, r) {
        (row || []).forEach(function(val, c) {
          var ref = String.fromCharCode(65 + c) + (r + 1);
          ws[ref] = {v: val, t: typeof val === 'number' ? 'n' : 's'};
        });
      });
      return ws;
    },
    
    book_new: function() { return {SheetNames: [], Sheets: {}}; },
    book_append_sheet: function(wb, ws, name) {
      wb.SheetNames.push(name);
      wb.Sheets[name] = ws;
    }
  };
  
  XLSX.writeFile = function(wb, filename) {
    // Generate CSV for download (simple fallback)
    var ws = wb.Sheets[wb.SheetNames[0]];
    var keys = Object.keys(ws).filter(k => /^[A-Z]+\d+$/.test(k));
    var maxRow = 0, maxCol = 0;
    keys.forEach(function(k) {
      var c = decodeCell(k);
      if (c) { maxRow = Math.max(maxRow, c.r); maxCol = Math.max(maxCol, c.c); }
    });
    
    var lines = [];
    for (var r = 0; r <= maxRow; r++) {
      var row = [];
      for (var c = 0; c <= maxCol; c++) {
        var ref = String.fromCharCode(65 + c) + (r + 1);
        var v = ws[ref] ? String(ws[ref].v || '') : '';
        if (v.includes(',') || v.includes('"') || v.includes('\n')) v = '"' + v.replace(/"/g, '""') + '"';
        row.push(v);
      }
      lines.push(row.join(','));
    }
    
    var csv = lines.join('\n');
    var blob = new Blob(['\uFEFF' + csv], {type: 'text/csv;charset=utf-8'});
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = filename.replace(/\.xlsx$/, '.csv');
    document.body.appendChild(a); a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };
  
  return XLSX;
})();
